 IF DATABASE() IS NULL OR COALESCE(@profile_workbench_s3_maintenance,0)!=1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 approved maintenance prerequisite missing'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='system_profile_workbench_task_visibility' AND COLUMN_NAME IN ('id','tenant_id','user_id','task_key','business_id','source','task_type','detail','hidden_at','creator','create_time','updater','update_time','deleted'))!=14 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 missing bootstrap columns: system_profile_workbench_task_visibility'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='dcc_controlled_file_distribution_recipient' AND COLUMN_NAME IN ('id','tenant_id','user_id','distribution_id'))!=4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 missing bootstrap columns: dcc_controlled_file_distribution_recipient'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='dcc_controlled_file_distribution' AND COLUMN_NAME IN ('id','tenant_id','controlled_file_id'))!=3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 missing bootstrap columns: dcc_controlled_file_distribution'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='dcc_controlled_file' AND COLUMN_NAME IN ('id','tenant_id'))!=2 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 missing bootstrap columns: dcc_controlled_file'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='dcc_controlled_file_training_progress' AND COLUMN_NAME IN ('id','tenant_id','user_id','controlled_file_id'))!=4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 missing bootstrap columns: dcc_controlled_file_training_progress'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='mes_pro_edhr_work_task' AND COLUMN_NAME IN ('id','tenant_id'))!=2 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 missing bootstrap columns: mes_pro_edhr_work_task'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='mes_pro_work_order' AND COLUMN_NAME IN ('id','tenant_id'))!=2 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 missing bootstrap columns: mes_pro_work_order'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='showroom_field_assignment' AND COLUMN_NAME IN ('id','tenant_id','notify_message_id','assignee_user_id'))!=4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 missing bootstrap columns: showroom_field_assignment'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='system_notify_message' AND COLUMN_NAME IN ('id','tenant_id','user_id','user_type'))!=4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 missing bootstrap columns: system_notify_message'; END IF;
 IF (SELECT COLLATION_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='system_profile_workbench_task_visibility' AND COLUMN_NAME='task_key')!='utf8mb4_0900_bin' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 binary NO PAD storage prerequisite missing'; END IF;
 START TRANSACTION;
 -- Existing ledger means complete replay, never incremental fill of mixed old/new history.
 IF EXISTS(SELECT 1 FROM system_workbench_visibility_key_ledger) AND
 ((SELECT COUNT(*) FROM system_workbench_visibility_key_ledger)!=(SELECT COUNT(*) FROM system_profile_workbench_task_visibility)
 OR EXISTS(SELECT 1 FROM system_profile_workbench_task_visibility v LEFT JOIN system_workbench_visibility_key_ledger l ON l.visibility_id=v.id WHERE l.visibility_id IS NULL OR CAST(v.task_key AS BINARY)!=CAST(l.stable_key AS BINARY))
 OR EXISTS(SELECT 1 FROM system_workbench_visibility_key_ledger l LEFT JOIN system_profile_workbench_task_visibility v ON v.id=l.visibility_id WHERE v.id IS NULL))
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 partial ledger or mixed legacy/stable state'; END IF;

 IF EXISTS(SELECT 1 FROM system_workbench_visibility_key_ledger l WHERE NOT ((CAST(l.source AS BINARY)=UNHEX('E69687E68EA7E58886E58F91') AND CAST(l.source_id AS BINARY)=CAST('DCC_DISTRIBUTION' AS BINARY) AND CAST(l.legacy_key AS BINARY)=CAST(CONCAT(CONVERT(UNHEX('E69687E68EA7E58886E58F91') USING utf8mb4),':',l.business_id) AS BINARY) AND CAST(l.stable_key AS BINARY)=CAST(CONCAT('DCC_DISTRIBUTION',':',l.business_id) AS BINARY)) OR (CAST(l.source AS BINARY)=UNHEX('E69687E68EA7E59FB9E8AEAD') AND CAST(l.source_id AS BINARY)=CAST('DCC_TRAINING' AS BINARY) AND CAST(l.legacy_key AS BINARY)=CAST(CONCAT(CONVERT(UNHEX('E69687E68EA7E59FB9E8AEAD') USING utf8mb4),':',l.business_id) AS BINARY) AND CAST(l.stable_key AS BINARY)=CAST(CONCAT('DCC_TRAINING',':',l.business_id) AS BINARY)) OR (CAST(l.source AS BINARY)=UNHEX('65444852E5B7A5E4BD9CE4BBBBE58AA1') AND CAST(l.source_id AS BINARY)=CAST('EDHR_WORK_TASK' AS BINARY) AND CAST(l.legacy_key AS BINARY)=CAST(CONCAT(CONVERT(UNHEX('65444852E5B7A5E4BD9CE4BBBBE58AA1') USING utf8mb4),':',l.business_id) AS BINARY) AND CAST(l.stable_key AS BINARY)=CAST(CONCAT('EDHR_WORK_TASK',':',l.business_id) AS BINARY)) OR (CAST(l.source AS BINARY)=UNHEX('E5BE85E68E92E4BAA7E5B7A5E58D95') AND CAST(l.source_id AS BINARY)=CAST('WORK_ORDER' AS BINARY) AND CAST(l.legacy_key AS BINARY)=CAST(CONCAT(CONVERT(UNHEX('E5BE85E68E92E4BAA7E5B7A5E58D95') USING utf8mb4),':',l.business_id) AS BINARY) AND CAST(l.stable_key AS BINARY)=CAST(CONCAT('WORK_ORDER',':',l.business_id) AS BINARY)) OR (CAST(l.source AS BINARY)=UNHEX('E5B195E58E85E8A1A5E58585E68C87E6B4BE') AND CAST(l.source_id AS BINARY)=CAST('SHOWROOM_ASSIGNMENT' AS BINARY) AND CAST(l.legacy_key AS BINARY)=CAST(CONCAT(CONVERT(UNHEX('E5B195E58E85E8A1A5E58585E68C87E6B4BE') USING utf8mb4),':',l.business_id) AS BINARY) AND CAST(l.stable_key AS BINARY)=CAST(CONCAT('SHOWROOM_ASSIGNMENT',':',l.business_id) AS BINARY)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 immutable ledger mapping differs'; END IF;
 -- No INSERT IGNORE, no cast until canonical positive ASCII decimal validation. Preserve completed/deleted.
 IF EXISTS(SELECT 1 FROM system_profile_workbench_task_visibility v WHERE v.tenant_id<0 OR v.user_id<=0 OR v.business_id IS NULL OR NOT REGEXP_LIKE(v.business_id,'^[1-9][0-9]{0,18}$','c') OR OCTET_LENGTH(v.business_id)!=CHAR_LENGTH(v.business_id) OR CHAR_LENGTH(v.business_id)>19 OR (CHAR_LENGTH(v.business_id)=19 AND CAST(v.business_id AS BINARY)>CAST('9223372036854775807' AS BINARY))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 invalid original identity, inspect visibility.id'; END IF;
 IF EXISTS(SELECT 1 FROM system_profile_workbench_task_visibility v LEFT JOIN system_workbench_visibility_key_ledger l ON l.visibility_id=v.id WHERE l.visibility_id IS NULL AND NOT ((CAST(v.source AS BINARY)=UNHEX('E69687E68EA7E58886E58F91') AND CAST(v.task_key AS BINARY)=CAST(CONCAT(CONVERT(UNHEX('E69687E68EA7E58886E58F91') USING utf8mb4),':',v.business_id) AS BINARY)) OR (CAST(v.source AS BINARY)=UNHEX('E69687E68EA7E59FB9E8AEAD') AND CAST(v.task_key AS BINARY)=CAST(CONCAT(CONVERT(UNHEX('E69687E68EA7E59FB9E8AEAD') USING utf8mb4),':',v.business_id) AS BINARY)) OR (CAST(v.source AS BINARY)=UNHEX('65444852E5B7A5E4BD9CE4BBBBE58AA1') AND CAST(v.task_key AS BINARY)=CAST(CONCAT(CONVERT(UNHEX('65444852E5B7A5E4BD9CE4BBBBE58AA1') USING utf8mb4),':',v.business_id) AS BINARY)) OR (CAST(v.source AS BINARY)=UNHEX('E5BE85E68E92E4BAA7E5B7A5E58D95') AND CAST(v.task_key AS BINARY)=CAST(CONCAT(CONVERT(UNHEX('E5BE85E68E92E4BAA7E5B7A5E58D95') USING utf8mb4),':',v.business_id) AS BINARY)) OR (CAST(v.source AS BINARY)=UNHEX('E5B195E58E85E8A1A5E58585E68C87E6B4BE') AND CAST(v.task_key AS BINARY)=CAST(CONCAT(CONVERT(UNHEX('E5B195E58E85E8A1A5E58585E68C87E6B4BE') USING utf8mb4),':',v.business_id) AS BINARY)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 unknown legacy label/key or unledgered stable row'; END IF;
 IF EXISTS(SELECT 1 FROM system_workbench_visibility_key_ledger l LEFT JOIN system_profile_workbench_task_visibility v ON v.id=l.visibility_id WHERE v.id IS NULL OR NOT ((v.tenant_id <=> l.tenant_id) AND (v.user_id <=> l.user_id) AND (CAST(v.task_type AS BINARY) <=> CAST(l.task_type AS BINARY)) AND (CAST(v.source AS BINARY) <=> CAST(l.source AS BINARY)) AND (CAST(v.business_id AS BINARY) <=> CAST(l.business_id AS BINARY)) AND (CAST(v.detail AS BINARY) <=> CAST(l.detail AS BINARY)) AND (v.hidden_at <=> l.hidden_at) AND (CAST(v.creator AS BINARY) <=> CAST(l.creator AS BINARY)) AND (v.create_time <=> l.create_time) AND (CAST(v.updater AS BINARY) <=> CAST(l.updater AS BINARY)) AND (v.update_time <=> l.update_time) AND (v.deleted <=> l.deleted)) OR NOT(CAST(v.task_key AS BINARY)=CAST(l.stable_key AS BINARY))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 immutable ledger drift or mixed prior state'; END IF;
 IF EXISTS(SELECT 1 FROM system_profile_workbench_task_visibility v LEFT JOIN dcc_controlled_file_distribution_recipient p ON p.id=CAST(v.business_id AS UNSIGNED) AND p.tenant_id=v.tenant_id AND p.user_id=v.user_id LEFT JOIN dcc_controlled_file_distribution d ON d.id=p.distribution_id AND d.tenant_id=v.tenant_id LEFT JOIN dcc_controlled_file f ON f.id=d.controlled_file_id AND f.tenant_id=v.tenant_id WHERE CAST(v.source AS BINARY)=UNHEX('E69687E68EA7E58886E58F91') AND (p.id IS NULL OR d.id IS NULL OR f.id IS NULL)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 historical DCC_DISTRIBUTION identity missing'; END IF;
 IF EXISTS(SELECT 1 FROM system_profile_workbench_task_visibility v LEFT JOIN dcc_controlled_file_training_progress p ON p.id=CAST(v.business_id AS UNSIGNED) AND p.tenant_id=v.tenant_id AND p.user_id=v.user_id LEFT JOIN dcc_controlled_file f ON f.id=p.controlled_file_id AND f.tenant_id=v.tenant_id WHERE CAST(v.source AS BINARY)=UNHEX('E69687E68EA7E59FB9E8AEAD') AND (p.id IS NULL OR f.id IS NULL)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 historical DCC_TRAINING identity missing'; END IF;
 IF EXISTS(SELECT 1 FROM system_profile_workbench_task_visibility v LEFT JOIN mes_pro_edhr_work_task p ON p.id=CAST(v.business_id AS UNSIGNED) AND p.tenant_id=v.tenant_id WHERE CAST(v.source AS BINARY)=UNHEX('65444852E5B7A5E4BD9CE4BBBBE58AA1') AND (p.id IS NULL)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 historical EDHR_WORK_TASK identity missing'; END IF;
 IF EXISTS(SELECT 1 FROM system_profile_workbench_task_visibility v LEFT JOIN mes_pro_work_order p ON p.id=CAST(v.business_id AS UNSIGNED) AND p.tenant_id=v.tenant_id WHERE CAST(v.source AS BINARY)=UNHEX('E5BE85E68E92E4BAA7E5B7A5E58D95') AND (p.id IS NULL)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 historical WORK_ORDER identity missing'; END IF;
 IF EXISTS(SELECT 1 FROM system_profile_workbench_task_visibility v LEFT JOIN showroom_field_assignment p ON p.id=CAST(v.business_id AS UNSIGNED) AND p.tenant_id=v.tenant_id AND p.assignee_user_id=v.user_id LEFT JOIN system_notify_message n ON n.id=p.notify_message_id AND n.tenant_id=v.tenant_id AND n.user_id=p.assignee_user_id AND n.user_type=2 WHERE CAST(v.source AS BINARY)=UNHEX('E5B195E58E85E8A1A5E58585E68C87E6B4BE') AND (p.id IS NULL OR n.id IS NULL)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 historical SHOWROOM_ASSIGNMENT identity missing'; END IF;
 INSERT INTO system_workbench_visibility_key_ledger(visibility_id,legacy_key,source_id,stable_key,tenant_id,user_id,task_type,source,business_id,detail,hidden_at,creator,create_time,updater,update_time,deleted) SELECT id,task_key,CASE WHEN CAST(source AS BINARY)=UNHEX('E69687E68EA7E58886E58F91') THEN 'DCC_DISTRIBUTION' WHEN CAST(source AS BINARY)=UNHEX('E69687E68EA7E59FB9E8AEAD') THEN 'DCC_TRAINING' WHEN CAST(source AS BINARY)=UNHEX('65444852E5B7A5E4BD9CE4BBBBE58AA1') THEN 'EDHR_WORK_TASK' WHEN CAST(source AS BINARY)=UNHEX('E5BE85E68E92E4BAA7E5B7A5E58D95') THEN 'WORK_ORDER' WHEN CAST(source AS BINARY)=UNHEX('E5B195E58E85E8A1A5E58585E68C87E6B4BE') THEN 'SHOWROOM_ASSIGNMENT' ELSE NULL END,CONCAT(CASE WHEN CAST(source AS BINARY)=UNHEX('E69687E68EA7E58886E58F91') THEN 'DCC_DISTRIBUTION' WHEN CAST(source AS BINARY)=UNHEX('E69687E68EA7E59FB9E8AEAD') THEN 'DCC_TRAINING' WHEN CAST(source AS BINARY)=UNHEX('65444852E5B7A5E4BD9CE4BBBBE58AA1') THEN 'EDHR_WORK_TASK' WHEN CAST(source AS BINARY)=UNHEX('E5BE85E68E92E4BAA7E5B7A5E58D95') THEN 'WORK_ORDER' WHEN CAST(source AS BINARY)=UNHEX('E5B195E58E85E8A1A5E58585E68C87E6B4BE') THEN 'SHOWROOM_ASSIGNMENT' ELSE NULL END,':',business_id),tenant_id,user_id,task_type,source,business_id,detail,hidden_at,creator,create_time,updater,update_time,deleted FROM system_profile_workbench_task_visibility v WHERE NOT EXISTS(SELECT 1 FROM system_workbench_visibility_key_ledger l WHERE l.visibility_id=v.id);
 -- uk_wb_stable includes deleted; legitimate active/deleted historical pairs stay separate.
 IF EXISTS(SELECT 1 FROM system_profile_workbench_task_visibility v LEFT JOIN system_workbench_visibility_key_ledger l ON l.visibility_id=v.id WHERE l.visibility_id IS NULL) OR (SELECT COUNT(*) FROM system_profile_workbench_task_visibility)!=(SELECT COUNT(*) FROM system_workbench_visibility_key_ledger) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 whole-history id set mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM system_workbench_visibility_context c JOIN (SELECT DISTINCT tenant_id,user_id FROM system_profile_workbench_task_visibility) h ON h.tenant_id=c.tenant_id AND h.user_id=c.user_id WHERE c.visibility_version!=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 existing historical context not version1'; END IF;
 INSERT INTO system_workbench_visibility_context(tenant_id,user_id,visibility_version) SELECT DISTINCT v.tenant_id,v.user_id,1 FROM system_profile_workbench_task_visibility v WHERE NOT EXISTS(SELECT 1 FROM system_workbench_visibility_context c WHERE c.tenant_id=v.tenant_id AND c.user_id=v.user_id);
 UPDATE system_profile_workbench_task_visibility v JOIN system_workbench_visibility_key_ledger l ON l.visibility_id=v.id
 SET v.task_key=l.stable_key,v.update_time=l.update_time
 WHERE CAST(v.task_key AS BINARY)!=CAST(l.stable_key AS BINARY);
 IF EXISTS(SELECT 1 FROM system_profile_workbench_task_visibility v JOIN system_workbench_visibility_key_ledger l ON l.visibility_id=v.id WHERE NOT ((v.tenant_id <=> l.tenant_id) AND (v.user_id <=> l.user_id) AND (CAST(v.task_type AS BINARY) <=> CAST(l.task_type AS BINARY)) AND (CAST(v.source AS BINARY) <=> CAST(l.source AS BINARY)) AND (CAST(v.business_id AS BINARY) <=> CAST(l.business_id AS BINARY)) AND (CAST(v.detail AS BINARY) <=> CAST(l.detail AS BINARY)) AND (v.hidden_at <=> l.hidden_at) AND (CAST(v.creator AS BINARY) <=> CAST(l.creator AS BINARY)) AND (v.create_time <=> l.create_time) AND (CAST(v.updater AS BINARY) <=> CAST(l.updater AS BINARY)) AND (v.update_time <=> l.update_time) AND (v.deleted <=> l.deleted)) OR CAST(v.task_key AS BINARY)!=CAST(l.stable_key AS BINARY)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 audit/content reconciliation failed'; END IF;
 IF EXISTS(SELECT 1 FROM system_profile_workbench_task_visibility v LEFT JOIN system_workbench_visibility_context c ON c.tenant_id=v.tenant_id AND c.user_id=v.user_id WHERE c.visibility_version IS NULL OR c.visibility_version!=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='S3 historical personal version reconciliation failed'; END IF;
 COMMIT;
END$$
